const N=9,L=6,V='v5.0.1',TV='0.166.1',RAW='https://raw.githubusercontent.com/bata-san/MMDer/main/';
const dec=new TextDecoder();
const notice=t=>{const e=document.querySelector('#notice');if(e)e.textContent=t};
const toast=t=>{const e=document.querySelector('#toast');if(!e)return;e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),4200)};
function b64(s){const x=atob(s.replace(/\s+/g,'')),a=new Uint8Array(x.length);for(let i=0;i<x.length;i++)a[i]=x.charCodeAt(i);return a}
async function gunzip(a){const s=new Blob([a]).stream().pipeThrough(new DecompressionStream('gzip'));return new Uint8Array(await new Response(s).arrayBuffer())}
function text(a,o,n){return dec.decode(a.subarray(o,o+n)).replace(/\0.*$/s,'').trim()}
function tar(a){const m=new Map();let o=0;while(o+512<=a.length){const h=a.subarray(o,o+512);if(h.every(v=>v===0))break;const n=text(h,0,100),p=text(h,345,155),q=p?`${p}/${n}`:n,z=parseInt(text(h,124,12)||'0',8),s=o+512,t=String.fromCharCode(h[156]||48);if((t==='0'||t==='\0')&&q)m.set(q.replace(/^\.\//,''),dec.decode(a.subarray(s,s+z)));o=s+Math.ceil(z/512)*512}return m}
async function get(rel,raw){let last;for(const u of [new URL(rel,import.meta.url).href,`${RAW}${raw}?v=5.0.1`])for(let i=0;i<2;i++){const c=new AbortController(),x=setTimeout(()=>c.abort(),12000);try{const r=await fetch(u,{cache:'no-store',signal:c.signal});if(!r.ok)throw Error(`${r.status} ${r.statusText}`);return await r.text()}catch(e){last=e}finally{clearTimeout(x)}}throw last||Error(`Failed to fetch ${raw}`)}
async function archive(files,rel,raw){for(const [p,s]of tar(await gunzip(b64(await get(rel,raw)))))files.set(p,s)}
function ext(s){if(s==='three')return`https://cdn.jsdelivr.net/npm/three@${TV}/build/three.module.js`;if(s.startsWith('three/addons/'))return`https://cdn.jsdelivr.net/npm/three@${TV}/examples/jsm/${s.slice(13)}`;return null}
function rep(src,s,r){const e=s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return src.replace(new RegExp(`(['"])${e}\\1`,'g'),JSON.stringify(r))}
function theme(v){const n=v==='light'?'light':'dark';document.documentElement.dataset.theme=n;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',n==='light'?'#eef1f5':'#0b0e14');window.dispatchEvent(new CustomEvent('mmdlab-theme-change',{detail:{theme:n}}));localStorage.setItem('mmd-lab-theme',n)}
function shell(){for(const [id,url]of[['theme-performance-style','../theme-performance.css?v=5.0.1'],['life-system-style','../life-system.css?v=5.0.1']])if(!document.getElementById(id)){const l=document.createElement('link');l.id=id;l.rel='stylesheet';l.href=new URL(url,import.meta.url).href;document.head.append(l)}const b=document.querySelector('#build-version');if(b)b.textContent=V;const s=document.querySelector('.status');if(s&&!document.querySelector('#theme-toggle')){const x=document.createElement('button');x.id='theme-toggle';x.className='theme-toggle';x.textContent='◐';x.title='白黒テーマ切替';x.onclick=()=>theme(document.documentElement.dataset.theme==='light'?'dark':'light');s.append(x)}theme(localStorage.getItem('mmd-lab-theme'))}
async function start(){shell();notice('LOADING RUNTIME…');const chunks=await Promise.all(Array.from({length:N},(_,i)=>{const n=`chunk-${String(i).padStart(2,'0')}`;return get(`../assets/verified-patch/${n}?v=5.0.1`,`assets/verified-patch/${n}`)}));const files=tar(await gunzip(b64(chunks.join(''))));try{await archive(files,'../assets/performance-patch?v=5.0.1','assets/performance-patch')}catch(e){console.warn('Performance patch unavailable.',e)}let life=true;try{const c=await Promise.all(Array.from({length:L},(_,i)=>{const n=`chunk-${String(i).padStart(2,'0')}`;return get(`../assets/life-runtime/${n}?v=5.0.1`,`assets/life-runtime/${n}`)}));for(const[p,s]of tar(await gunzip(b64(c.join('')))))files.set(p,s)}catch(e){life=false;console.warn('Life runtime unavailable; using stable core.',e)}const ov=new Map();for(const[p,o]of files){if(!p.startsWith('dist/')||!p.endsWith('.js'))continue;const s=p==='dist/state.js'?o.replace(/BUILD_VERSION\s*=\s*['"]v[^'"]+['"]/,`BUILD_VERSION = '${life?V:V+' SAFE'}'`):o;ov.set(new URL(`../${p}`,import.meta.url).href,s)}const cache=new Map();async function mod(u){u=new URL(u).href;if(cache.has(u))return cache.get(u);const p=(async()=>{let s=ov.get(u);if(s===undefined){const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw Error(`Module unavailable: ${new URL(u).pathname}`);s=await r.text()}s=s.replace(/new URL\(\s*(['"])(\.[^'"]+)\1\s*,\s*import\.meta\.url\s*\)/g,(_m,_q,r)=>`new URL(${JSON.stringify(new URL(r,u).href)})`);const ex=new Set();for(const m of s.matchAll(/\b(?:from|import)\s*['"]([^'"]+)['"]/g))if(!m[1].startsWith('.'))ex.add(m[1]);for(const x of ex){const r=ext(x);if(r)s=rep(s,x,r)}const re=new Set();for(const m of s.matchAll(/\b(?:from|import)\s*['"](\.[^'"]+)['"]/g))re.add(m[1]);for(const x of re)s=rep(s,x,await mod(new URL(x,u).href));return URL.createObjectURL(new Blob([s],{type:'text/javascript'}))})();cache.set(u,p);return p}await import(await mod(new URL('./app.js',import.meta.url).href));if(!life)toast('生命ランタイムを取得できなかったため安定版で起動しました')}
start().catch(e=>{console.error('Runtime failed to start.',e);notice('RUNTIME LOAD ERROR');toast(`起動に失敗しました: ${e instanceof Error?e.message:String(e)}`)});
